 { image: 'https://swiperjs.com/demos/images/nature-2.jpg' },
 { image: 'https://swiperjs.com/demos/images/nature-3.jpg' },
 ];
 }
 });
 }

 ngAfterViewInit() {
 this.zone.runOutsideAngular(() => {
 const swiperParams = {
 breakpoints: {
 100: {
 slidesPerView: 3,
 },
 640: {
 slidesPerView: 5,
 },
 1024: {
 slidesPerView: 6,
 },
 },
 };

 const swiperParams1 = {
 spaceBetween: 10
 };

 Object.assign(this.swiper2.nativeElement, swiperParams1);
 this.swiper1.nativeElement.initialize();

 // now we need to assign all parameters to Swiper element
 Object.assign(this.swiper2.nativeElement, swiperParams);
 this.swiper2.nativeElement.initialize();
 });
 }
}

answer:
To ensure both main and thumb Swipers initialize correctly without reinitializing twice, you can run initialization logic outside of the Angular zone using `NgZone`. Here’s how to do it:

1. Import necessary modules and services.
2. Use `runOutsideAngular` to initialize Swiper components.

```typescript
import { Component, OnInit, ViewChild, ElementRef, NgZone } from '@angular/core';

@Component({
  selector: 'app-swiper-thumbs-vertical-dup-1',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './swiper-thumbs-vertical-dup-1.component.html',
  styleUrls: ['./swiper-thumbs-vertical-dup-1.component.scss']
})
export class SwiperThumbsVerticalDup1Component implements OnInit {
  @ViewChild('swiper1') swiper1!: ElementRef;
  @ViewChild('swiper2') swiper2!: ElementRef;

  constructor(private zone: NgZone) {}

  ngOnInit() {
    this.zone.runOutsideAngular(() => {
      const swiperParams = { /* your main Swiper params */ };
      const swiperParams1 = { spaceBetween: 10 };

      Object.assign(this.swiper2.nativeElement, swiperParams1);
      this.swiper1.nativeElement.initialize();

      // Assign all parameters to the thumb Swiper
      Object.assign(this.swiper2.nativeElement, swiperParams);
      this.swiper2.nativeElement.initialize();
    });
  }
}
```

This approach ensures that both Swipers are initialized only once when Angular routing changes.

