<script setup>
import { ref } from 'vue';
import { useForm } from '@inertiajs/vue3';

const selectedButtons = ref([]);

function updateSelectedButtons(button) {
  if (selectedButtons.value.includes(button)) {
    selectedButtons.value = selectedButtons.value.filter(b => b !== button);
  } else {
    selectedButtons.value.push(button);
  }
}
</script>
```

2. **Form Submission**: Ensure the `submit` function correctly handles form data.

```vue
<script setup>
const submit = () => {
  form.post('/message', { buttons: selectedButtons.value });
};
</script>

<template>
  <form @submit.prevent="submit">
    <!-- Other form fields -->
    <button type="submit">Send Message</button>
  </form>
</template>
```

This approach ensures that only the selected checkboxes are submitted, avoiding issues with `selectAll`.

