    });
}
```

2. In your `resources/views/auth/register.blade.php`, you can now use the `$genders` variable to populate the dropdown:

```blade
<div>
    <label for="gender">Select Gender</label>
    <select name="gender" id="gender">
        @foreach ($genders as $gender)
            <option value="{{ $gender->id }}">{{ $gender->name }}</option>
        @endforeach
    </select>
</div>
```

This approach can be extended to other models like `countries` by adjusting the query and passing it similarly. For example, if you have a `Countries` model:

```php
use App\Models\Countries;

public function boot(): void
{
    Fortify::registerView(function () {
        return view('auth.register', ['countries' => Countries::all()]);
    });
}
```

And in the blade file:

```blade
<div>
    <label for="country">Select Country</label>
    <select name="country" id="country">
        @foreach ($countries as $country)
            <option value="{{ $country->id }}">{{ $country->name }}</option>
        @endforeach
    </select>
</div>
```

This method ensures your dropdowns are dynamically populated from the database.

