  ],
  bootstrap: [AppComponent]
})
export class AppModule {}
```

Ensure `OktaAuthStateService` is imported at the top of your `app.module.ts`. This setup ensures that `OktaAuthStateService` is available throughout your application, resolving the `NullInjectorError`.

