 idleState = 'Not started.';
 timedOut = false;
 lastPing?: Date = null;
 title1 = 'angular-idle-timeout';
 expiredDate: Date;
 constructor(@Inject(WINDOW) private window: any,
 @Inject(PLATFORM_ID) private platformId: Object,
 public router: Router,
 public activatedRoute: ActivatedRoute,
 public titleService: Title,
 public meta: Meta,
 public cookieService: CookieService,
 public dataService: DataService,
 public loaderSVC: LoaderService,
 public seoService: SeoService,
 public idle: Idle,
 ) { 

 idle.setIdle(600);
 idle.setTimeout(600);
 idle.setInterrupts(DEFAULT_INTERRUPTSOURCES);

 idle.onTimeout.subscribe(() => {
 this.timedOut = true;
 localStorage.removeItem('authorisationToken');
 this.router.navigate(['/']);
 });
 this.reset();
 this.serverName = environment.name;

 this.activatedRoute.queryParams.subscribe(params => {
 let utm_CampaignSource = params['utm_CampaignSource'];
 let getCookie = this.cookieService.get('utm_fetch');

 if (utm_CampaignSource && (!getCookie)) {
 const dateNow = new Date();
 dateNow.setMinutes(dateNow.getMinutes() + 30);
 this.cookieService.set('utm_fetch', "Yes", dateNow, '', '', true);
 }
 });

 }

 reset() {
 this.idle.watch();
 this.timedOut = false;
 }

 ngAfterViewInit(): void {
 this.router.events.subscribe(event => {
 if (event instanceof NavigationEnd && isPlatformBrowser(this.platformId)) {
 if (this.serverName == "production") {
 ga('set', 'page', event.urlAfterRedirects);
 ga('send', 'pageview');
 }
 }
 });
 }

 ngOnInit() {
 this.seoService.createLinkForCanonicalURL();
 this.router.events.subscribe((evt) => {
 this.loaderSVC.startLoading(); 
 if (!(evt instanceof NavigationEnd)) {
 return;
 }
 setTimeout(() => {
 this.loaderSVC.stopLoading(); 
 });
 if (isPlatformBrowser(this.platformId)) {
 window.scrollTo(0, 0);

 const userAgent = window.navigator.userAgent;
 sessionStorage.setItem('userAgent', userAgent);
 sessionStorage.setItem('ipAddress', '0.0.0.0');
 }
 });

 this.router.events
 .filter((event) => event instanceof NavigationEnd)
 .map(() => this.activatedRoute)
 .map((route) => {
 while (route.firstChild) route = route.firstChild;
 return route;
 })
 .filter((route) => route.outlet === 'primary')
 .mergeMap((route) => route.data)
 .subscribe((event) => {
 this.updateDescription(event['description'], event['keywords'], event['title']);
 });
 }

 updateDescription(desc: string, keywords: string, title: string) {
 if (title) {
 this.titleService.setTitle(title);
 }
 if (desc) {
 this.meta.updateTag({ name: 'description', content: desc })
 }
 /*if(keywords){
 this.meta.updateTag({ name: 'keywords', content: keywords })
 }*/
 }
}

We have tried to update
this.router.events.filter
with
this.router.events.pipe(filter(event => event instanceof NavigationEnd)
But don't know how to map after that

answer:
The issue arises because `this.router.events` does not have a `filter` method directly available. You need to use RxJS's `pipe` and `filter` operators together. Here’s how you can correct your code:

```typescript
import { filter, map } from 'rxjs/operators';

// ...

this.router.events.pipe(
  filter((event) => event instanceof NavigationEnd),
  map(() => this.activatedRoute)
).subscribe(route => {
  while (route.firstChild) route = route.firstChild;
  if (route.outlet === 'primary') {
    const data = route.data;
    this.updateDescription(data['description'], data['keywords'], data['title']);
  }
});
```

This approach uses RxJS's `pipe` to chain the `filter` and `map` operators, ensuring that only `NavigationEnd` events are processed. Then, it navigates through the route tree to find the primary outlet and updates metadata accordingly.

Make sure you import `filter`, `map` from 'rxjs/operators' at the top of your file.

